use xiom.io;

module my_project {
  pub type AppState = {
    ticks: Int;
  }

  pub fn init() -> AppState {
    return AppState{ ticks: 0 };
  }

  pub fn update(state: &mut AppState) {
    state.ticks += 1;
  }

  pub fn render(state: &AppState) {
    io.println("tick " + state.ticks.to_str());
  }
}

fn main() -> Int {
  var state = my_project.init();
  my_project.update(&mut state);
  my_project.render(&state);
  return 0;
}
